-- Catálogo PARCIAL, corte de revisión 2026-11-10, exclusivamente fuentes oficiales DIAN.
-- Ejecutar parametrizado con $1 = empresa_id, dentro de transacción y lock por empresa.
-- Solo INSERT: conserva estados, tarifas, nombres editados y registros personalizados.
-- El índice por código evita reinsertar conceptos renombrados; nombre también es UNIQUE.
-- Vigencia 572/2025: suspensión 07/05/2026, levantamiento 02/06/2026.
-- Efectos operativos: mes siguiente a ejecutoria; NO se certificó esa fecha exacta.
-- Fuente: 11001-03-27-000-2025-00055-00(30229)_20260602.htm y Oficio 15000/2026.
WITH contexto AS (
    SELECT 'https://normograma.dian.gov.co/dian/compilacion/docs/'::text AS url,
           ' Verificar agente retenedor, beneficiario, residencia, régimen SIMPLE y excepciones antes de aplicar. '
           'Catálogo parcial al 2026-11-10, no motor de liquidación ni tabla histórica de todo 2026. '
           'Las bases del Decreto 572/2025 corresponden al régimen restablecido tras levantarse la suspensión; '
           'no aplicar retrospectivamente al intervalo suspendido.'::text AS alcance
), datos (codigo, nombre, grupo, porcentaje, base_calculo, base_minima_uvt,
          condicion, norma, documento, seleccionable) AS (
    VALUES
    ('RF_COMPRAS_DECLARANTE', 'Retefuente - Compras generales declarantes 2,5%', 'RENTA', 2.5::numeric, 'PAGO', 10::numeric,
     'Desde 10 UVT (>=). Solo otros ingresos sin regla especial; beneficiario obligado a declarar. Excluir impuestos incorporados en las condiciones del parágrafo 1.',
     'ET 401; DUR 1625/2016 art. 1.2.4.9.1, literal i y parágrafos 1 y 3; D. 572/2025 art. 6.',
     'decreto_1625_2016.htm#1.2.4.9.1', TRUE),
    ('RF_COMPRAS_NO_DECLARANTE', 'Retefuente - Compras generales no declarantes 3,5%', 'RENTA', 3.5, 'PAGO', 10,
     'Desde 10 UVT (>=). Beneficiario no obligado a declarar; no reemplaza tarifas especiales de vehículos, construcción, agro u otros conceptos.',
     'ET 401; DUR 1625/2016 art. 1.2.4.9.1, literal i y parágrafo 3; D. 572/2025 art. 6.',
     'estatuto_tributario.htm#401', TRUE),
    ('RF_SERVICIOS_DECLARANTE', 'Retefuente - Servicios generales declarantes 4%', 'RENTA', 4, 'PAGO', 2,
     'Desde 2 UVT (>=). Servicios sin tarifa especial y sin aplicación de ET 383. Incluye supuestos de persona natural no declarante del art. 1.2.4.4.14 por contrato o acumulado superior a 3300 UVT.',
     'ET 392; DUR 1625/2016 arts. 1.2.4.4.1 y 1.2.4.4.14; D. 572/2025 art. 2.',
     'decreto_1625_2016.htm#1.2.4.4.14', TRUE),
    ('RF_SERVICIOS_NO_DECLARANTE', 'Retefuente - Servicios generales no declarantes 6%', 'RENTA', 6, 'PAGO', 2,
     'Desde 2 UVT (>=). No obligado a declarar, sin supuesto especial de 4% del art. 1.2.4.4.14 ni aplicación de ET 383; no es tarifa universal de servicios.',
     'ET 392; DUR 1625/2016 arts. 1.2.4.4.1 y 1.2.4.4.14; D. 572/2025 art. 2.',
     'estatuto_tributario.htm#392', TRUE),
    ('RF_HONORARIOS_PJ', 'Retefuente - Honorarios y comisiones personas jurídicas 11%', 'RENTA', 11, 'PAGO', 0,
     'Sin mínimo general en UVT en esta regla. Personas jurídicas y asimiladas; verificar reglas sectoriales especiales.',
     'ET 392; DUR 1625/2016 art. 1.2.4.3.1.',
     'decreto_1625_2016.htm#1.2.4.3.1', TRUE),
    ('RF_HONORARIOS_PN', 'Retefuente - Honorarios y comisiones personas naturales 10%', 'RENTA', 10, 'PAGO', 0,
     'Sin mínimo general. Solo cuando no corresponde ET 383 ni el supuesto del 11% por contrato/acumulado superior a 3300 UVT. No basta identificar al beneficiario como no declarante.',
     'ET 392; DUR 1625/2016 art. 1.2.4.3.1; art. 1.2.4.1.17 parágrafo 4; Concepto 6997/2025.',
     'decreto_1625_2016.htm#1.2.4.3.1', TRUE),
    ('RF_HONORARIOS_PN_3300', 'Retefuente - Honorarios personas naturales supuesto 3300 UVT 11%', 'RENTA', 11, 'PAGO', 0,
     'Sin mínimo general. Si contrato o acumulado anual con el mismo agente supera 3300 UVT, aplicar según literales a/b; en acumulado, desde el pago que exceda. Excluir casos de ET 383.',
     'DUR 1625/2016 art. 1.2.4.3.1, literales a y b. 3300 UVT no es la base mínima de esta tarifa.',
     'decreto_1625_2016.htm#1.2.4.3.1', TRUE),
    ('RF_SOFTWARE_DECLARANTE', 'Retefuente - Software y licenciamiento declarantes 3,5%', 'RENTA', 3.5, 'PAGO', 0,
     'Sin mínimo en el parágrafo. Solo actividades de software enumeradas, licenciamiento/derecho de uso, residentes o domiciliados obligados a declarar. No extender a todo producto tecnológico ni a pagos al exterior; verificar ET 383.',
     'DUR 1625/2016 art. 1.2.4.3.1 parágrafo.',
     'decreto_1625_2016.htm#1.2.4.3.1', TRUE),
    ('RF_AGRO_SIN_PROCESAMIENTO', 'Retefuente - Agro sin procesamiento industrial 1,5%', 'RENTA', 1.5, 'PAGO', 70,
     'Obligatoria cuando EXCEDE 70 UVT (>), no desde la igualdad. Hasta 70 UVT el agente puede optar por no retener. No extender a productos procesados industrialmente.',
     'DUR 1625/2016 art. 1.2.4.6.7; D. 572/2025 art. 3.',
     'decreto_1625_2016.htm#1.2.4.6.7', TRUE),
    ('RF_CAFE_PERGAMINO_CEREZA', 'Retefuente - Café pergamino o cereza 0,5%', 'RENTA', 0.5, 'PAGO', 70,
     'Solo cuando EXCEDE 70 UVT (>). Sumar compras de una misma fecha entre el mismo vendedor y comprador; no generalizar a cualquier café procesado.',
     'DUR 1625/2016 art. 1.2.4.6.8 y parágrafo; D. 572/2025 art. 4.',
     'decreto_1625_2016.htm#1.2.4.6.8', TRUE),
    ('RF_TEMPORALES_AIU', 'Retefuente - Empresas de servicios temporales sobre AIU 1%', 'RENTA', 1, 'AIU', 2,
     'Desde 2 UVT (>=) del valor de la operación, NO del AIU. Si cumple ET 462-1, aplicar al AIU, no inferior al 10% del contrato; requiere autorización y obligaciones laborales/seguridad social. No aplicar al total del pago.',
     'ET 462-1; DUR 1625/2016 arts. 1.2.4.4.1 y 1.2.4.4.10; Concepto 16207/2026 reconsidera 5224 y 10208/2026.',
     'oficio_dian_16207_2026.htm', TRUE),
    ('RF_ASEO_VIGILANCIA_AIU', 'Retefuente - Aseo y vigilancia sobre AIU 2%', 'RENTA', 2, 'AIU', 2,
     'Desde 2 UVT (>=) del valor de la operación. Solo servicios comprendidos en ET 462-1 y sus condiciones: aplicar al AIU, no inferior al 10% del contrato. No convertir cualquier aseo o vigilancia en base AIU.',
     'ET 462-1; DUR 1625/2016 art. 1.2.4.4.10; Concepto 16207/2026, párrs. 19 a 26.',
     'oficio_dian_16207_2026.htm', TRUE),
    ('RF_SALUD_IPS', 'Retefuente - Servicios integrales de salud IPS 2%', 'RENTA', 2, 'PAGO', 2,
     'Desde 2 UVT (>=). Servicios integrales de salud prestados por IPS que reúnen servicios calificados y no calificados; no tarifa universal de honorarios médicos.',
     'ET 392, inciso de servicios integrales de salud; DUR 1625/2016 art. 1.2.4.4.1.',
     'estatuto_tributario.htm#392', TRUE),
    ('RF_CARGA_TERRESTRE', 'Retefuente - Transporte terrestre de carga 1%', 'RENTA', 1, 'PAGO', 2,
